// data/documents/disciplinary-act.js
//
// The full text of the JLA Disciplinary Procedure Act, converted from the
// source .docx and rendered on-page by common/DocumentReader.jsx.
// PDF: public/documents/jladisciplinary.pdf
//
// CLAUSE NUMBERS WERE RECOVERED, NOT INVENTED
// Like the Attendance Policy, this Act numbers its clauses with Word's
// automatic numbering, so the visible "1." / "a." markers are generated by
// Word and absent from the extracted text. Numbering was rebuilt from the
// document's numbering definitions (numId / ilvl / numFmt) and counted in
// document order: 7 top-level clauses, with clause 3 containing an
// eight-step procedure lettered a. through h.
//
// TEXT IS VERBATIM, INCLUDING ERRORS
// Preserved exactly as written, including the heading's "DISPLINARY"
// (the body line spells it "DISCIPLINARY") and the double space in
// clause 7's "committee  will". This is an enacted procedure; correcting
// it here would publish text differing from the signed document. Fix the
// source .docx, then re-convert.
//
// ⚠️ NOT ADOPTED: the certification block carries an unfilled date
// ("the ____ day of __________ 20____"). The Act names itself
// "Disciplinary Procedure Policy, 2026" but records no adoption date, so
// none is displayed. See `certification` below.
//
// ⚠️ SEQUENCING WORTH A LEGAL REVIEW (not a conversion issue — the source
// reads this way): clause 3(h) has the committee reach and communicate a
// reasoned decision; clauses 4–6 then run the appeal and declare the
// appeal decision final; clause 7 then says the disciplinary committee
// "thereafter" determines the verdict at its discretion. As written, a
// verdict appears to follow a final appeal. Flagging rather than
// silently reordering — this is the Alliance's text to fix, not the
// converter's.

const disciplinaryAct = {
  id: "disciplinary-act",
  title: "Juris Leadership Alliance Disciplinary Procedure Act",
  shortTitle: "Disciplinary Procedure Act",
  sectionLabel: "Clause",
  version: "2026",

  intro:
    "This Act serves as the amicable procedure to be followed after an office bearer or a member has committed an act that contravenes the constitution or that act that goes against the Organization\u2019s, not limited to subject, purpose and belief.",

  clauses: [
    {
      id: "clause-1",
      number: 1,
      text: "A person may be subjected to disciplinary action if he/she contravenes any of the provisions of the (JURIS LEADERSHIP ALLIANCE hereafter known as JLA) Constitution.",
      blocks: [],
    },
    {
      id: "clause-2",
      number: 2,
      text: "Any member can lodge a complaint, in written form, through the Head of discipline.",
      blocks: [],
    },
    {
      id: "clause-3",
      number: 3,
      text: "The disciplinary procedure shall be as follows;",
      blocks: [
        {
          type: "list",
          numeral: "lowerLetter",
          items: [
            "A member lodging a complaint against another is to do so within 21 days from the date of occurrence of the alleged misconduct.",
            "The disciplinary committee (shall consist of the Executive Committee Members) investigates the alleged misconduct and determines whether there is a reasonable basis for commencing the disciplinary process.",
            "If a reasonable basis is established the member is to be issued with a formal written notice detailing the exact allegations, the evidence gathered and the potential consequences.",
            "The accused is therefore required to issue a response towards the allegations within 7 days.",
            "The accused response is reviewed to determine whether his/her explanation satisfactorily addresses the allegations or whether further disciplinary action is necessary.",
            "The disciplinary hearing begins and the accused shall have the right to representation.",
            "During the disciplinary hearing, the accused should be given a genuine opportunity to present their defense, challenge the allegations, provide supporting evidence, and, where appropriate, call witnesses or respond to evidence presented against them.",
            "After considering all the evidence presented during the disciplinary process, the disciplinary committee should make a reasoned and objective decision which shall be communicated in writing.",
          ],
        },
      ],
    },
    {
      id: "clause-4",
      number: 4,
      text: "An individual dissatisfied with the decision of the disciplinary committee has a right to appeal against that decision within 7 days.",
      blocks: [],
    },
    {
      id: "clause-5",
      number: 5,
      text: "The appeal shall be heard by a separate ad hoc appeals committee that was not involved in the initial decision.",
      blocks: [],
    },
    {
      id: "clause-6",
      number: 6,
      text: "The decision on appeal shall be final.",
      blocks: [],
    },
    {
      id: "clause-7",
      number: 7,
      text: "Thereafter, the disciplinary committee  will determine the verdict of the individual at their discretion.",
      blocks: [],
    },
  ],

  certification: {
    // Reproduced verbatim. The date fields are blank in the source.
    text:
      "This Disciplinary Procedure Policy, 2026, was duly adopted by the General Assembly of the Organization on the ____ day of __________________ 20____ and shall constitute the governing disciplinary procedural laws subject to the Constitution.",
    signatories: ["Chairperson", "Secretary General", "Official Seal (where applicable)"],
    adopted: false, // no date recorded — do not display an adoption date
  },
};

// --- Derived helpers -----------------------------------------------------

export const clauseIndex = disciplinaryAct.clauses.map((c) => ({
  id: c.id,
  number: c.number,
  title: c.text.replace(/[;:]$/, ""),
}));

// The eight-step procedure from clause 3, surfaced as an ordered process
// so DocumentReader can render it as a stepper rather than a wall of
// lettered sub-clauses. `text` is the verbatim provision; `deadline` is
// the time limit stated IN that provision, lifted out for display — no
// deadline is inferred where the source doesn't state one.
export const procedureSteps = disciplinaryAct.clauses
  .find((c) => c.number === 3)
  .blocks[0].items.map((text, i) => {
    const deadlines = {
      0: "Within 21 days of the alleged misconduct",
      3: "Response due within 7 days",
    };
    return {
      step: i + 1,
      letter: String.fromCharCode(97 + i), // a, b, c ...
      text,
      deadline: deadlines[i] || null,
    };
  });

// Deadlines stated anywhere in the Act, for an at-a-glance summary. Each
// cites the clause it comes from so a reader can verify it against the
// text rather than trusting this list.
export const deadlines = [
  { label: "Lodge a complaint", limit: "21 days", source: "Clause 3(a)" },
  { label: "Respond to allegations", limit: "7 days", source: "Clause 3(d)" },
  { label: "Lodge an appeal", limit: "7 days", source: "Clause 4" },
];

export const getClause = (id) =>
  disciplinaryAct.clauses.find((c) => c.id === id) || null;

export default disciplinaryAct;